patches.colleagueRiskBlock:
const global=V('global/preset','STRING',L('Средний','Medium')),gp=V('global/position','STRING',L('На позицию: 20,00 $','Per position: $20.00')),gd=V('global/daily','STRING',L('Покупки за день: 30,00 $','Daily buys: $30.00')),ga=V('global/age','STRING',L('Давность сигнала: 30 сек','Signal age: 30 sec'));
newFrame('global-risk',L('Общие правила риска','Global risk rules'));newFrame('custom-risk',L('Лимиты выбранного трейдера','Selected trader limits'));
clear('global-risk');card(ct['global-risk'],L('Общие значения для новых настроек','Defaults for new setups'),L('Изменение общих правил не перестраивает уже запущенные сессии без вашей проверки. Для трейдера можно использовать общие правила или задать собственные.','Changing defaults does not silently update running sessions. Each trader can use defaults or their own values.'));for(const v of [global,gp,gd,ga])text(ct['global-risk'],'Global value','',14,v);
for(const [name,p,d,a]of [[L('Низкий','Low'),1000,2000,15],[L('Средний','Medium'),2000,3000,30],[L('Высокий','High'),4000,6000,60]])await button(ct['global-risk'],name,[set(global,name),set(gp,L('На позицию: ','Per position: ')+money(p)),set(gd,L('Покупки за день: ','Daily buys: ')+money(d)),set(ga,L('Давность сигнала: ','Signal age: ')+a+L(' сек',' sec'))]);
await button(ct['global-risk'],L('Сохранить общие правила','Save global rules'),[nav(fs.profile.id)],true);
clear('custom-risk');text(ct['custom-risk'],'Selected trader','',24,E('trader/title'));card(ct['custom-risk'],L('Собственные лимиты','Custom limits'),L('Они применяются к выбранному трейдеру. Бюджет демо в этом сценарии — 200 $.','These apply to the selected trader. The demo budget in this flow is $200.'));
for(const [label,key,values]of [[L('На позицию','Per position'),'position',[10,20,40]],[L('Покупки за день','Daily buys'),'daily',[20,30,60]],[L('Давность сигнала','Signal age'),'age',[15,30,60]]]){text(ct['custom-risk'],'Custom value','',14,V('risk/'+key));await row(ct['custom-risk'],values.map(value=>[key==='age'?value+L(' сек',' sec'):money(value*100),[set(V('risk/'+key),label+': '+(key==='age'?value+L(' сек',' sec'):money(value*100))),set(V('risk/preset'),L('Свои лимиты','Custom limits'))]]));}
await button(ct['custom-risk'],L('Применить к трейдеру','Apply to trader'),[nav(fs.setup.id)],true);
for(const n of ct.setup.findAllWithCriteria({types:['INSTANCE']})){if(n.name==='Action / '+L('Настроить вручную','Customize limits'))await react(n,[nav(fs['custom-risk'].id)]);if(n.name==='Action / '+L('Использовать общие правила','Use global rules'))await react(n,[...[[V('risk/preset'),global],[V('risk/position'),gp],[V('risk/daily'),gd],[V('risk/age'),ga]].map(([to,from])=>({type:'SET_VARIABLE',variableId:to.id,variableValue:{type:'VARIABLE_ALIAS',resolvedType:'STRING',value:{type:'VARIABLE_ALIAS',id:from.id}}}))]);}
for(const n of ct.profile.findAllWithCriteria({types:['INSTANCE']}))if(/Общие правила риска|Global risk rules/.test(n.name))await react(n,[nav(fs['global-risk'].id)]);
if(!ct.profile.findOne(n=>/Общие правила риска|Global risk rules/.test(n.name)))await button(ct.profile,L('Общие правила риска','Global risk rules'),[nav(fs['global-risk'].id)]);
const r=ct.entry.findOne(n=>n.name==='Action / '+L('Вернуться к черновику','Resume a draft'));const first=section.findOne(n=>n.name==='Item / trader / trader-01');if(r&&first)await react(r,first.reactions[0].actions.filter(a=>a.type!=='NODE').concat(r.reactions[0].actions));
const home=[{type:'CONDITIONAL',conditionalBlocks:[{condition:eq(vm.get('Review/SessionStage'),'before'),actions:[nav(fs.before.id)]},{condition:eq(vm.get('Review/SessionStage'),'empty'),actions:[nav(fs.fresh.id)]},{actions:[nav(fs.home.id)]}]}];
for(const k of ['trader-24h','trader-7d','trader-30d','trader-90d'])for(const n of ct[k].findAllWithCriteria({types:['INSTANCE']}))if(n.name==='Action / '+L('Моя демо-сессия','My demo session'))await react(n,home);
for(const f of [fs['global-risk'],fs['custom-risk']]){for(const n of f.findAll(x=>'reactions'in x)){if(/Profile.*(avatar|Open account)/.test(n.name))await react(n,[nav(fs.profile.id)]);if(/Balance/.test(n.name))await react(n,[nav(fs.funds.id)]);}}
page.flowStartingPoints=[{nodeId:fs.entry.id,name:L((desk?'ПК':'Мобильный')+' · Русский',(desk?'Desktop':'Mobile')+' · English')}];changed.add(page.id);
return {pageId:page.id,createdNodeIds:[...created],mutatedNodeIds:[...changed],createdVariableIds:createdVars,globalFrame:fs['global-risk'].id,customFrame:fs['custom-risk'].id,entryId:fs.entry.id};

patches.colleagueFinalParityCode:
const froms=[V('global/preset'),V('global/position'),V('global/daily'),V('global/age')],tos=[V('risk/preset'),V('risk/position'),V('risk/daily'),V('risk/age')];
const useGlobals=froms.map((from,i)=>({type:'SET_VARIABLE',variableId:tos[i].id,variableValue:{type:'VARIABLE_ALIAS',resolvedType:'STRING',value:{type:'VARIABLE_ALIAS',id:from.id}}}));
if(!ct.setup.findOne(n=>n.name==='Action / '+L('Настроить вручную','Customize limits')))await button(ct.setup,L('Настроить вручную','Customize limits'),[nav(fs['custom-risk'].id)]);
if(!ct.setup.findOne(n=>n.name==='Action / '+L('Использовать общие правила','Use global rules')))await button(ct.setup,L('Использовать общие правила','Use global rules'),useGlobals);
for(const k of ['trader-24h','trader-7d','trader-30d','trader-90d']){const n=text(ct[k],'Recommended budget',L('Рекомендуемый бюджет: пока не рассчитан. Минимум для запуска указан выше.','Recommended budget: not calculated yet. Launch minimum is shown above.'));const configure=ct[k].children.find(x=>x.name==='Fix / configure selected trader');if(configure)ct[k].insertChild(ct[k].children.indexOf(configure),n);}
const genericReturn=nav(fs.setup.id);for(const f of page.findAllWithCriteria({types:['FRAME']}).filter(f=>f.parent.type==='SECTION'&&f.parent!==section&&/U08a|D07a|Расширенные настройки|Advanced.*settings/i.test(f.name)))for(const n of f.findAll(x=>'reactions'in x&&x.reactions.length)){const t=n.type==='TEXT'?n:n.findOne?.(x=>x.type==='TEXT');if(t&&/Сохранить|Save|Применить|Apply|Назад|Back/.test(t.characters))await react(n,[genericReturn]);}
if(ru){function localize(as){return as.map(a=>a.type==='CONDITIONAL'?{...a,conditionalBlocks:a.conditionalBlocks.map(b=>({...b,actions:localize(b.actions)}))}:a.type==='SET_VARIABLE'&&a.variableValue?.type==='STRING'?{...a,variableValue:{...a.variableValue,value:a.variableValue.value.replace(/(\d+)\.(\d+)(?=%)/g,'$1,$2').replace(/(^|\s)-(?=\d)/g,'$1−')}}:a);}for(const n of section.findAll(x=>'reactions'in x&&x.reactions.length)){const next=n.reactions.map(r=>({...r,actions:localize(r.actions||[])}));if(JSON.stringify(next)!==JSON.stringify(n.reactions)){await n.setReactionsAsync(next);changed.add(n.id);}}}
return {pageId:page.id,createdNodeIds:[...created],mutatedNodeIds:[...changed],createdVariableIds:createdVars,frames:Object.fromEntries(Object.entries(fs).map(([k,f])=>[k,f.id]))};

patches.colleagueCleanupBlock:
await button(ct.help,L('Как работает копирование','How copying works'),[nav(fs.onboarding.id)]);
for(const t of section.findAllWithCriteria({types:['TEXT']}))if(t.name==='Balance context'&&t.reactions?.length){await t.setReactionsAsync([]);changed.add(t.id);}
const ordered=[section,...page.children.filter(n=>n.type==='SECTION'&&n!==section)];let y=100;for(const n of ordered){n.x=100;n.y=y;y+=n.height+240;changed.add(n.id);}
return {pageId:page.id,createdNodeIds:[...created],mutatedNodeIds:[...changed]};

patches.colleagueFavoritePatch:
let updated=0;for(const [i,m]of DATA.markets.entries()){
const favor=V('market/'+m.id+'/favorite','BOOLEAN',false),not=V('market/'+m.id+'/not-favorite','BOOLEAN',true),visible=V('market/'+m.id+'/visible','BOOLEAN',true),view=V('markets/view','STRING','all');
not.setValueForMode(coll.defaultModeId,!favor.valuesByMode[coll.defaultModeId]);
const bs=ct.markets.findAllWithCriteria({types:['INSTANCE']}).filter(n=>n.parent.findOne?.(t=>t.type==='TEXT'&&t.characters===(ru?m.labelRu:m.label)));
for(const b of bs){const t=b.findOne(n=>n.type==='TEXT');if(!t)continue;if(['В избранное','Add to favorites'].includes(t.characters)){b.setBoundVariable('visible',not);await react(b,[set(favor,true),set(not,false)]);updated++;}
if(['Убрать из избранного','Remove favorite'].includes(t.characters)){b.setBoundVariable('visible',favor);await react(b,[set(favor,false),set(not,true),cond(eq(view,'favorite'),[set(visible,false)])]);updated++;}}
}
for(const b of ct.markets.findAllWithCriteria({types:['INSTANCE']})){const t=b.findOne(n=>n.type==='TEXT');if(!t||!['Все','All','Избранное','Favorites','Новые','New','Скоро завершатся','Ending soon'].includes(t.characters))continue;const mode=/Избранное|Favorites/.test(t.characters)?'favorite':/Новые|New/.test(t.characters)?'new':/Скоро|Ending/.test(t.characters)?'ending':'all';const actions=b.reactions[0]?.actions||[];await react(b,[set(V('markets/view','STRING','all'),mode),...actions]);}return {updated};
